  "source": "\"\"\"Offline geometry of closed development AP snapshots; truth never controls.\"\"\"\nimport hashlib,json,math\nfrom pathlib import Path\nfrom types import SimpleNamespace\nfrom multi_robot_exploration import control as c\nfrom multi_robot_exploration.task_evaluator import load_truth_grid\nfrom multi_robot_exploration.target_detector import line_of_sight_clear,target_visible\n\nROS=Path.cwd();world=ROS/'src/multi_robot/worlds/my_world.world';truth=load_truth_grid(world)\ndef ns(d):return SimpleNamespace(**{k:ns(v) if isinstance(v,dict) else v for k,v in d.items()})\ndef yaw(q):return math.atan2(2*(q['w']*q['z']+q['x']*q['y']),1-2*(q['y']**2+q['z']**2))\ndef angle(a):return math.atan2(math.sin(a),math.cos(a))\nrows=[]\nroots=[ROS/'log/p3b5/p3b5_v61_dev_fixed_ap',ROS/'log/p3b5/p3b5_v61_dev_task_ap']\nfor root in roots:\n    for source in sorted(root.glob('*/snapshots.jsonl')):\n        frames=[]\n        for line in source.open():\n            f=json.loads(line);m=f['messages'];event=m.get('target_detection')\n            if event is None:continue\n            det=json.loads(event['data']);target=(det['target_x'],det['target_y'])\n            observation=dict(observer_time=f['observer_time'],task_state=m['task_state']['data'],\n                confirmation_source=det['stamp_sec'],confirmation_age=f['observer_time']-det['stamp_sec'],\n                confirmed_robot=det['robot'],robots={},assignments=json.loads(m['rally_assignments']['data']) if 'rally_assignments' in m else None)\n            for n in ('tb1','tb2','tb3'):\n                od=m.get(n+'/odom');tf=m.get(n+'/tf');battery=m.get(n+'/battery_state')\n                if od is None or tf is None or battery is None:continue\n                transform=next((t['transform'] for t in tf['transforms'] if t['header']['frame_id'].endswith('map') and t['child_frame_id'].endswith('odom')),None)\n                if transform is None:continue\n                p=od['pose']['pose']['position'];position=c.transform_point_2d(p['x'],p['y'],ns(transform))\n                heading=angle(yaw(od['pose']['pose']['orientation'])+yaw(transform['rotation']))\n                b=json.loads(battery['data'])\n                observation['robots'][n]=dict(ap_position=position,ap_yaw=heading,energy=b['energy'],mode=b['mode'],\n                    static_truth_los_at_ap_pose=line_of_sight_clear(truth,position,target),\n                    static_truth_visible_at_ap_pose=target_visible((*position,heading),target,truth,det['max_distance_m'],math.radians(det['field_of_view_deg'])),\n                    target_bearing_error=angle(math.atan2(target[1]-position[1],target[0]-position[0])-heading))\n            frames.append(observation)\n        rows.append(dict(snapshot_path=str(source),snapshot_sha256=hashlib.sha256(source.read_bytes()).hexdigest(),frames=frames))\nout=dict(scope=__doc__,world_sha256=hashlib.sha256(world.read_bytes()).hexdigest(),rows=rows,\n    limitation='Static SDF geometry evaluated at independent AP reconstructed poses, not native synchronized model poses or original controller buffers. Localization/yaw/source age can differ; this is forensic evidence, not a new policy, exact camera reconstruction or causal trial.',source=Path(__file__).read_text())\ndestination=Path('/tmp/p3b5_v61_observation_geometry.json');assert not destination.exists();destination.write_text(json.dumps(out,indent=2)+'\\n')\nfor row in rows:\n    if 'fixed_lab101' not in row['snapshot_path'] and 'zero_ideal' not in row['snapshot_path']:continue\n    print(row['snapshot_path']);print(json.dumps(row['frames'],indent=2))\n"
